const sources = $input.all();
if (!sources || sources.length === 0) {
  return [{ json: { _skip: true, reason: 'No active Instagram sources' } }];
}
const sourceMap = {};
const directUrls = [];
const seenHandles = new Set();
const scanDates = [];

for (const s of sources) {
  let handle = (s.json['Instagram_Handle'] || '').replace(/^@/, '').trim();
  if (!handle) {
    const url = (s.json['Instagram_Links'] || s.json['Links'] || '');
    const match = url.match(/instagram\.com\/([^/?#]+)/);
    if (match && !['p','reel','tv','explore','stories'].includes(match[1])) handle = match[1].trim();
  }
  if (!handle) continue;

  const key = handle.toLowerCase();
  if (seenHandles.has(key)) {
    console.log('[2a] Duplicate handle skipped: @' + handle);
    continue;
  }
  seenHandles.add(key);

  const profileUrl = 'https://www.instagram.com/' + handle + '/';
  directUrls.push(profileUrl);

  const lastScanned = s.json['Instagram_Last_Scanned'] || '';
  sourceMap[key] = {
    source_id: s.json.id || '',
    source_name: s.json['Source Name'] || '',
    handle: '@' + handle,
    last_scanned: lastScanned
  };
  if (lastScanned) scanDates.push(lastScanned);
}

if (!directUrls.length) {
  return [{ json: { _skip: true, reason: 'No valid handles found' } }];
}

// Weekly incremental. Apify's onlyPostsNewerThan is unreliable, so we request a
// modest window here AND enforce a hard cutoff in node 3 by published_at.
// Floor for the Apify request: oldest last-scanned date, or 8-day default.
const GLOBAL_DEFAULT_DAYS = 8;
let onlyNewerThan;
const allScanned = scanDates.length === directUrls.length && scanDates.length > 0;
if (allScanned) {
  const oldest = scanDates.sort()[0];
  onlyNewerThan = oldest;
  console.log('[2a] All sources scanned. Apify floor: ' + oldest);
} else {
  onlyNewerThan = GLOBAL_DEFAULT_DAYS + ' days';
  console.log('[2a] ' + (directUrls.length - scanDates.length) + ' unscanned source(s). Apify window: ' + onlyNewerThan);
}

console.log('[2a] ' + directUrls.length + ' unique profiles | onlyPostsNewerThan=' + onlyNewerThan);
return [{ json: { directUrls, source_map: sourceMap, only_newer_than: onlyNewerThan } }];

const apifyInput = $('2a. Prepare Apify Input').first().json;
const sourceMap = apifyInput.source_map || {};

const allPosts = $input.all()
  .map(i => i.json)
  .filter(v => v && typeof v === 'object' && !v.error);

console.log('[3] Apify returned ' + allPosts.length + ' total posts');

if (!allPosts.length) {
  return [{ json: { _skip: true, video_id: '', source_id: '', source_name: '', url: '' } }];
}

// HARD RECENCY CUTOFF. Apify's onlyPostsNewerThan is unreliable and returns old
// posts (e.g. 2024). We enforce recency here by published date. A post is kept only
// if newer than that source's last-scanned date. If a source was never scanned,
// fall back to GLOBAL_FALLBACK_DAYS so a brand-new source still can't pull deep history.
const GLOBAL_FALLBACK_DAYS = 8;
const now = Date.now();
const fallbackCutoffMs = now - GLOBAL_FALLBACK_DAYS * 24 * 60 * 60 * 1000;

function sourceCutoffMs(username) {
  const info = sourceMap[username] || {};
  const ls = info.last_scanned || '';
  if (ls) {
    const t = Date.parse(ls);
    if (!isNaN(t)) return t;
  }
  return fallbackCutoffMs;
}

function postTimeMs(post) {
  // Apify returns timestamp as ISO string; takenAtTimestamp as unix seconds.
  const ts = post.timestamp || '';
  if (ts) {
    const t = Date.parse(ts);
    if (!isNaN(t)) return t;
  }
  const unix = parseInt(post.takenAtTimestamp || 0);
  if (unix > 0) return unix * 1000;
  return 0; // unknown date -> will be dropped by cutoff
}

const results = [];
let droppedOld = 0;

for (const post of allPosts) {
  const postType = (post.type || post.productType || post.__typename || '').toUpperCase();
  if (postType === 'IMAGE' || postType === 'CAROUSEL_ALBUM' || postType === 'SIDECAR') continue;

  const username = (post.ownerUsername || post.username || '').toLowerCase().trim();

  // RECENCY GATE
  const pTime = postTimeMs(post);
  const cutoff = sourceCutoffMs(username);
  if (pTime <= cutoff) { droppedOld++; continue; }

  const sourceInfo = sourceMap[username] || { source_id: '', source_name: username, handle: '@' + username };

  const postId = String(post.id || post.shortCode || '');
  if (!postId) continue;

  const parseNum = (val) => {
    if (val == null) return 0;
    const s = String(val).replace(/,/g, '').trim();
    if (s.endsWith('M')) return Math.round(parseFloat(s) * 1000000);
    if (s.endsWith('K')) return Math.round(parseFloat(s) * 1000);
    return parseInt(s) || 0;
  };

  const viewCount = parseNum(post.videoPlayCount || post.videoViewCount || post.playsCount || 0);
  const likeCount = parseNum(post.likesCount || post.likes || 0);
  const commentCount = parseNum(post.commentsCount || post.comments || 0);
  const duration = parseInt(post.videoDuration || post.duration || 0);
  const caption = post.caption || post.text || post.description || '';
  const shortCode = post.shortCode || post.id || '';
  const url = post.url || ('https://www.instagram.com/reel/' + shortCode + '/');
  const publishedAt = post.timestamp || post.takenAtTimestamp || '';

  let tags = '';
  const hashtagMatches = caption.match(/#[\w\u0080-\uFFFF]+/g);
  if (hashtagMatches) tags = hashtagMatches.map(h => h.replace(/^#/, '')).join(', ');

  results.push({
    json: {
      video_id: postId, source_id: sourceInfo.source_id, source_name: sourceInfo.source_name,
      handle: sourceInfo.handle, title: caption.substring(0, 500), description: caption.substring(0, 500),
      tags, url, view_count: viewCount, like_count: likeCount, comment_count: commentCount,
      duration, published_at: publishedAt, channel_id: username, content_type: 'Reel', platform: 'Instagram'
    }
  });
}

console.log('[3] Dropped ' + droppedOld + ' posts older than cutoff. Kept ' + results.length + ' recent.');

if (!results.length) {
  return [{ json: { _skip: true, video_id: '', source_id: '', source_name: '', url: '' } }];
}

// Per-creator baseline median (last 30 videos) for outlier scoring. Framework Part 1.1.
// DEFENSIVE: node 4 runs downstream; guard the reference.
const historyByChannel = {};
let _existingRecs = [];
try {
  _existingRecs = $('4. Get All Existing Video IDs').all();
} catch (e) {
  console.log('[3] node 4 not executed this run, using current-run median');
}
for (const rec of _existingRecs) {
  const ch = (rec.json['Channel ID'] || '').toLowerCase().trim();
  if (!ch) continue;
  const v = parseInt(rec.json['View Count']) || 0;
  const ts = rec.json['Published At'] || '';
  if (!historyByChannel[ch]) historyByChannel[ch] = [];
  historyByChannel[ch].push({ v, ts });
}

function median(arr) {
  if (!arr.length) return 0;
  const s = [...arr].sort((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  return s.length % 2 === 0 ? (s[mid - 1] + s[mid]) / 2 : s[mid];
}

const currentByChannel = {};
for (const r of results) {
  const ch = r.json.channel_id;
  if (!currentByChannel[ch]) currentByChannel[ch] = [];
  currentByChannel[ch].push({ v: r.json.view_count, ts: r.json.published_at });
}

const baselineByChannel = {};
const allChannels = new Set([...Object.keys(historyByChannel), ...Object.keys(currentByChannel)]);
for (const ch of allChannels) {
  const combined = [...(historyByChannel[ch] || []), ...(currentByChannel[ch] || [])]
    .filter(x => x.v > 0)
    .sort((a, b) => String(b.ts).localeCompare(String(a.ts)))
    .slice(0, 30)
    .map(x => x.v);
  baselineByChannel[ch] = median(combined);
}

const scored = [];
for (const r of results) {
  const baseline = baselineByChannel[r.json.channel_id] || 0;
  const outlierScore = baseline > 0 ? parseFloat((r.json.view_count / baseline).toFixed(2)) : 0;
  scored.push({ json: { ...r.json, outlier_score: outlierScore, baseline_median: baseline } });
}

console.log('[3] Total extracted (recent): ' + scored.length);
return scored;

const existingItems = $input.all();
const existingIds = new Set(existingItems.map(i => i.json['Video ID'] || '').filter(id => id !== ''));
const incomingItems = $('3. Extract & Flatten Instagram Posts').all();
const seenThisRun = new Set();
const newVideos = incomingItems.filter(item => {
  if (item.json._skip) return false;
  const vid = item.json.video_id;
  if (!vid || existingIds.has(vid) || seenThisRun.has(vid)) return false;
  seenThisRun.add(vid);
  return true;
});
console.log('[5] Apify: ' + incomingItems.length + ' | Existing: ' + existingIds.size + ' | New: ' + newVideos.length);
if (newVideos.length === 0) return [{ json: { _skip: true, video_id: '', source_id: '', source_name: '', url: '' } }];
return newVideos;

// Gate 1 per AlfredAI Outlier & Relevance Scoring Framework: OS >= 2.0x
// Tiers: Mega-Viral (>5.0), Strong Outlier (2.0-5.0). Below 2.0 rejected.
const OUTLIER_THRESHOLD = 2.0;
const items = $input.all();
const outliers = [];
const skipped = [];

function tierFor(score) {
  if (score > 5.0) return 'Tier 1: Mega-Viral';
  if (score >= 2.0) return 'Tier 2: Strong Outlier';
  return null;
}

for (const item of items) {
  if (item.json._skip) continue;
  const score = parseFloat(item.json.outlier_score) || 0;
  const views = parseInt(item.json.view_count) || 0;
  const title = (item.json.title || '').substring(0, 50);
  const source = item.json.source_name || '';
  const tier = tierFor(score);
  if (tier) {
    outliers.push({ json: { ...item.json, _skip: false, is_outlier: true, outlier_threshold: OUTLIER_THRESHOLD, outlier_tier: tier } });
  } else {
    skipped.push(source + ': "' + title + '" (score=' + score + ', views=' + views + ')');
  }
}

if (skipped.length > 0) {
  console.log('[5b] Skipped ' + skipped.length + ' below 2.0x:');
  for (const s of skipped.slice(0, 10)) console.log('  - ' + s);
  if (skipped.length > 10) console.log('  ... and ' + (skipped.length - 10) + ' more');
}
console.log('[5b] Outliers: ' + outliers.length + ' / ' + items.length + ' (Gate 1 threshold: ' + OUTLIER_THRESHOLD + 'x)');
if (outliers.length === 0) return [{ json: { _skip: true, video_id: '', source_id: '', source_name: '', url: '' } }];
return outliers;

const sources = $('1. Get Active Instagram Sources').all();
const allVLRecords = $('9a. Get Video Library Counts').all();
const actualCountByName = {};
for (const rec of allVLRecords) {
  const sn = rec.json['Source Name'] || '';
  if (sn) actualCountByName[sn] = (actualCountByName[sn] || 0) + 1;
}
const results = [];
for (const source of sources) {
  const sourceName = source.json['Source Name'] || '';
  const sourceId = source.json.id;
  const today = new Date().toISOString().split('T')[0];
  results.push({ json: {
    source_id: sourceId,
    source_name: sourceName,
    videos_found: actualCountByName[sourceName] || 0,
    last_scanned: today
  }});
}
console.log('[9b] Updating ' + results.length + ' sources');
return results;
